module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);

    // State encoding: 2'b00 = A, 2'b01 = B, 2'b10 = C, 2'b11 = D
    reg [1:0] state, next_state;

    // State register (synchronous active high reset)
    always @(posedge clk) begin
        if (reset)
            state <= 2'b00;  // A
        else
            state <= next_state;
    end

    // Next-state logic (Moore machine)
    always @(*) begin
        case (state)
            2'b00: begin // State A, out = 0
                if (in)
                    next_state = 2'b01; // A --in=1--> B
                else
                    next_state = 2'b00; // A --in=0--> A
            end
            2'b01: begin // State B, out = 0
                if (in)
                    next_state = 2'b01; // B --in=1--> B
                else
                    next_state = 2'b10; // B --in=0--> C
            end
            2'b10: begin // State C, out = 0
                if (in)
                    next_state = 2'b11; // C --in=1--> D
                else
                    next_state = 2'b00; // C --in=0--> A
            end
            2'b11: begin // State D, out = 1
                if (in)
                    next_state = 2'b10; // D --in=1--> C
                else
                    next_state = 2'b01; // D --in=0--> B
            end
            default: next_state = 2'b00;
        endcase
    end

    // Output logic (Moore: output depends only on state)
    assign out = (state == 2'b11) ? 1'b1 : 1'b0;

endmodule

