module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal flip-flop outputs
    reg q_xor;
    reg q_and;
    reg q_or;

    // D flip-flop for XOR gate: second input is its own output
    always @(posedge clk) begin
        q_xor <= x ^ q_xor;
    end

    // D flip-flop for AND gate: second input is complemented output
    always @(posedge clk) begin
        q_and <= x & ~q_and;
    end

    // D flip-flop for OR gate: second input is complemented output
    always @(posedge clk) begin
        q_or  <= x | ~q_or;
    end

    // Three-input NOR gate: output is Z
    assign z = ~(q_xor | q_and | q_or);

endmodule

