module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 received bytes
    logic [23:0] shift_reg;

    // FSM state transition logic (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-asserted

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        shift_reg  <= {in, 16'b0}; // byte 1 goes to [23:16]
                        done       <= 1'b0;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive byte 2
                    next_state <= BYTE2;
                    shift_reg  <= {shift_reg[15:0], in}; // shift in byte 2 to [15:8]
                    done       <= 1'b0;
                end

                BYTE2: begin
                    // Receive byte 3
                    next_state <= BYTE3;
                    shift_reg  <= {shift_reg[7:0], in};   // shift in byte 3 to [7:0]
                    done       <= 1'b0;
                end

                BYTE3: begin
                    // All 3 bytes received; output and go IDLE next cycle
                    out_bytes <= shift_reg;
                    done      <= 1'b1;
                    next_state <= IDLE;
                end
            endcase
        end
    end

endmodule

