    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    // Internal signal to hold the 3-bit state (q[2:0])
    reg [2:0] q;

    // Sequential logic: D flip-flop with load and shift behavior
    always @(posedge clk) begin
        if (L) begin
            // Load mode: shift in r_in as the new MSB (q[2])
            // and shift the previous q[1] and q[0] down
            q <= {q[1] ^ q[2], q[0], r_in};
        end else begin
            // Shift mode: shift in q_in as the new MSB (q[2])
            // and shift the previous q[1] and q[0] down
            q <= {q[1] ^ q[2], q[0], q_in};
