module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT,    // 0
        WALK_RIGHT,   // 1
        FALLING,      // 2
        DIGGING,      // 3
        SPLATTERED    // 4
    } state_t;

    state_t state, next_state;

    // Outputs (Moore machine - outputs depend only on state)
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // State register (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state    <= WALK_LEFT;
            fall_cnt <= 0;
            walk_dir <= 1'b0;
        end else begin
            state    <= next_state;
        end
    end

    // Fall duration counter (5 bits enough for 0-31 > 20)
    logic [4:0] fall_cnt;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            fall_cnt <= 0;
        end else begin
            // Reset counter when ground appears
            if (ground) begin
                fall_cnt <= 0;
            end else if (state == FALLING) begin
                // Increment counter while falling and ground=0
                if (fall_cnt < 31)
                    fall_cnt <= fall_cnt + 1;
            end
        end
    end

    // Register to remember walking direction before fall
    logic walk_dir; // 1 = right, 0 = left

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            walk_dir <= 1'b0;
        end else begin
            // Save direction when starting to fall (from walking state)
            if (state == WALK_LEFT && next_state == FALLING) begin
                walk_dir <= 1'b0;
            end else if (state == WALK_RIGHT && next_state == FALLING) begin
                walk_dir <= 1'b1;
            end
            // When ground reappears and not splattered, resume walking direction
            if (ground && state != SPLATTERED) begin
                // Direction is preserved in walk_dir from before fall
            end
        end
    end

    // Next-state logic
    always_comb begin
        next_state = state; // default: stay in current state

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fall immediately when ground disappears
                    next_state = FALLING;
                end else if (dig) begin
                    // Start digging when walking on ground
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    // Switch direction when bumped (both sides switches to left)
                    next_state = WALK_RIGHT;
                end
                // else stay WALK_LEFT
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                end else if (dig) begin
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    // Switch direction when bumped (both sides switches to right)
                    next_state = WALK_LEFT;
                end
                // else stay WALK_RIGHT
            end

            FALLING: begin
                if (ground) begin
                    // Hit ground - check splatter condition
                    if (fall_cnt > 20) begin
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in same direction as before the fall
                        if (walk_dir)
                            next_state = WALK_RIGHT;
                        else
                            next_state = WALK_LEFT;
                    end
                end else begin
                    // Still falling, stay in FALLING
                end
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached other side, fall
                    next_state = FALLING;
                end else begin
                    // Still on ground, continue digging
                    // dig=1 continues digging; dig=0 does not stop once started
                    next_state = DIGGING;
                end
            end

            SPLATTERED: begin
                // Forever stuck, no transitions
                next_state = SPLATTERED;
            end
        endcase
    end

endmodule

