module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    wire [2:0] s_synced;
    reg  [2:0] s_prev;
    reg  [2:0] s_prev2;
    reg        dfr_reg;
    reg        fr0_reg, fr1_reg, fr2_reg;

    // Synchronize inputs
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            s_prev     <= 3'b000;
            s_prev2    <= 3'b000;
            dfr_reg    <= 1'b0;
            fr0_reg    <= 1'b1;
            fr1_reg    <= 1'b1;
            fr2_reg    <= 1'b1;
        end else begin
            s_prev     <= s;
            s_prev2    <= s_prev;
            dfr_reg    <= 1'b0;
            // Default assignments based on current level and history
            // Level logic: 000=low, 001, 010, 011, 100, 101, 110, 111=high
            case (s)
                3'b111, 3'b110, 3'b101: begin // Above s[2] or between s[2]&s[1]
                    fr0_reg <= 1'b0;
                    fr1_reg <= 1'b0;
                    fr2_reg <= 1'b0;
                    dfr_reg <= 1'b0;
                end
                3'b100, 3'b011: begin // Between s[2]&s[1] and Between s[1]&s[0]
                    fr0_reg <= 1'b1;
                    fr1_reg <= 1'b0;
                    fr2_reg <= 1'b0;
                    dfr_reg <= 1'b0;
                end
                3'b010, 3'b001, 3'b000: begin // Between s[1]&s[0] and Below s[0]
                    fr0_reg <= 1'b1;
                    fr1_reg <= 1'b1;
                    fr2_reg <= 1'b1;
                    // Increase flow if previous level was lower
                    if (s_prev2 < s) begin
                        dfr_reg <= 1'b1;
                    end
                end
            endcase
        end
    end

    // Output assignments
    assign fr0 = fr0_reg;
    assign fr1 = fr1_reg;
    assign fr2 = fr2_reg;
    assign dfr = dfr_reg;

    // Active-high synchronous reset handling (state equivalent to long low level)
    // Already handled in the always block above: reset sets all outputs and dfr to max state.

endmodule

